<!doctype html><html><head><meta charset="utf-8"><title>{{ $purchase->purchase_number }}</title><style>body{font-family:DejaVu Sans,Arial,sans-serif;color:#172033;font-size:12px;margin:32px}h1{margin:0 0 4px;font-size:25px}h2{font-size:15px;margin:22px 0 8px}.top{display:flex;justify-content:space-between;border-bottom:2px solid #172033;padding-bottom:18px}.muted{color:#667085}.box{border:1px solid #dfe4ec;border-radius:8px;padding:12px;margin-top:14px}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid #e7eaf0;text-align:left}th{font-size:10px;text-transform:uppercase}.right{text-align:right}.total{font-size:17px;font-weight:bold}.footer{margin-top:35px;color:#667085;text-align:center}@media print{body{margin:15mm}.no-print{display:none}}</style></head><body><div class="top"><div><h1>JALVAN</h1><div class="muted">Custom Branded Water Bottles · Supplier Purchase</div></div><div><strong>{{ $purchase->purchase_number }}</strong><br>{{ $purchase->purchase_date?->format('d M Y') }}</div></div><div class="box"><strong>Supplier</strong><br>{{ $purchase->supplier->business_name }}<br>{{ $purchase->supplier->contact_name }} · {{ $purchase->supplier->mobile }}<br>{{ $purchase->supplier->address }} {{ $purchase->supplier->city }} {{ $purchase->supplier->state }} {{ $purchase->supplier->pincode }}<br>GSTIN: {{ $purchase->supplier->gstin ?: '—' }}</div><h2>Items</h2><table><thead><tr><th>Description</th><th>Qty</th><th>Unit Cost</th><th>Tax</th><th class="right">Total</th></tr></thead><tbody>@foreach($purchase->items as $i)<tr><td>{{ $i->description }}</td><td>{{ $i->quantity }} {{ $i->unit }}</td><td>₹{{ number_format((float)$i->unit_price,2) }}</td><td>₹{{ number_format((float)$i->tax_amount,2) }}</td><td class="right">₹{{ number_format((float)$i->line_total,2) }}</td></tr>@endforeach</tbody></table><div class="box"><table><tr><td>Subtotal</td><td class="right">₹{{ number_format((float)$purchase->subtotal,2) }}</td></tr><tr><td>Discount</td><td class="right">₹{{ number_format((float)$purchase->discount_amount,2) }}</td></tr><tr><td>Tax</td><td class="right">₹{{ number_format((float)$purchase->tax_amount,2) }}</td></tr><tr><td>Shipping</td><td class="right">₹{{ number_format((float)$purchase->shipping_amount,2) }}</td></tr><tr><td>Other</td><td class="right">₹{{ number_format((float)$purchase->other_amount,2) }}</td></tr><tr><td class="total">Grand Total</td><td class="right total">₹{{ number_format((float)$purchase->grand_total,2) }}</td></tr></table></div><h2>Terms & Notes</h2><div class="box">{!! nl2br(e($purchase->terms_conditions ?: 'No terms added.')) !!}<br><br>{!! nl2br(e($purchase->notes ?: 'No notes.')) !!}</div><div class="footer">JALVAN · Thank you</div></body></html>
